    private LinkedMessages(){ }
    public static String get(String language,int key){
        if(key<0 || key>=COUNT)throw new IllegalArgumentException("Unknown linked label");
        String code=UiMessages.normalize(language);String[] locales=UiMessages.supportedLocales();
        for(int i=0;i<locales.length;i++)if(locales[i].equals(code))return TEXT[i][key];
        return TEXT[0][key];
    }
